import json
import datetime

MENU = [
    {'id': 'egg-crepe', 'name': 'Egg crepe', 'price_cents': 350, 'soldOut': False},
    {'id': 'radish-cake', 'name': 'Radish cake', 'price_cents': 400, 'soldOut': False},
    {'id': 'teppan-noodles', 'name': 'Teppan noodles', 'price_cents': 550, 'soldOut': False},
    {'id': 'chicken-nuggets', 'name': 'Chicken nuggets', 'price_cents': 450, 'soldOut': False},
    {'id': 'milk-tea', 'name': 'Milk tea', 'price_cents': 300, 'soldOut': False},
    {'id': 'soy-milk', 'name': 'Soy milk', 'price_cents': 250, 'soldOut': False},
]
MENU_BY_ID = {m['id']: m for m in MENU}
MENU_INDEX = {m['id']: i for i, m in enumerate(MENU)}
STATUSES = ['todo', 'cooking', 'done']
ORDER_TYPES = ['dine_in', 'take_out']

ORDERS = []
NEXT_ID = [1]


def _parse_body(body):
    if not body:
        return {}, None
    try:
        data = json.loads(body.decode('utf-8'))
    except (ValueError, UnicodeDecodeError):
        return None, 'Request body must be valid JSON.'
    if not isinstance(data, dict):
        return None, 'Request body must be a JSON object.'
    return data, None


def _item_view(m):
    return dict(m, price=m['price_cents'] / 100.0)


def _menu_view():
    return [_item_view(m) for m in MENU]


def _set_sold_out(item_id, body):
    item = MENU_BY_ID.get(item_id)
    if item is None:
        return 404, {'error': 'Menu item not found.'}
    data, err = _parse_body(body)
    if err:
        return 400, {'error': err}
    sold_out = data.get('soldOut')
    if not isinstance(sold_out, bool):
        return 400, {'error': 'soldOut must be true or false.'}
    item['soldOut'] = sold_out
    return 200, {'item': _item_view(item)}


def _create_order(body):
    data, err = _parse_body(body)
    if err:
        return 400, {'error': err}

    table = data.get('table')
    if isinstance(table, bool) or table is None:
        return 400, {'error': 'Table number is required.'}
    if isinstance(table, (int, float)):
        if isinstance(table, float) and table != int(table):
            return 400, {'error': 'Table number is not valid.'}
        table = str(int(table))
    if not isinstance(table, str):
        return 400, {'error': 'Table number is not valid.'}
    table = table.strip()
    if not table:
        return 400, {'error': 'Table number is required.'}
    if len(table) > 20:
        return 400, {'error': 'Table number is too long.'}

    order_type = data.get('order_type', data.get('orderType'))
    if not isinstance(order_type, str) or order_type not in ORDER_TYPES:
        return 400, {'error': 'Please choose Dine in or Take out (order_type must be dine_in or take_out).'}

    items = data.get('items')
    if not isinstance(items, list) or len(items) == 0:
        return 400, {'error': 'An order needs at least one item.'}

    merged = {}
    for entry in items:
        if not isinstance(entry, dict):
            return 400, {'error': 'Each item must be an object with id and quantity.'}
        item_id = entry.get('id')
        qty = entry.get('quantity')
        if not isinstance(item_id, str) or item_id not in MENU_BY_ID:
            return 400, {'error': 'Unknown menu item.'}
        if isinstance(qty, bool) or not isinstance(qty, int) or qty < 1:
            return 400, {'error': 'Quantities must be positive whole numbers.'}
        if MENU_BY_ID[item_id]['soldOut']:
            return 409, {'error': '%s is sold out.' % MENU_BY_ID[item_id]['name']}
        merged[item_id] = merged.get(item_id, 0) + qty
        if merged[item_id] > 99:
            return 400, {'error': 'Quantity per item is limited to 99.'}

    order_items = []
    total = 0
    for item_id, qty in merged.items():
        m = MENU_BY_ID[item_id]
        order_items.append({
            'id': item_id,
            'name': m['name'],
            'price_cents': m['price_cents'],
            'quantity': qty,
        })
        total += m['price_cents'] * qty

    order = {
        'id': NEXT_ID[0],
        'table': table,
        'order_type': order_type,
        'items': order_items,
        'total_cents': total,
        'total': total / 100.0,
        'status': 'todo',
        'created_at': datetime.datetime.now().isoformat(timespec='seconds'),
    }
    NEXT_ID[0] += 1
    ORDERS.append(order)
    return 201, {'order': order}


def _list_orders(body):
    data, err = _parse_body(body)
    if err:
        return 400, {'error': err}
    status = data.get('status')
    if status is not None and status != '':
        if status not in STATUSES:
            return 400, {'error': 'Status must be todo, cooking or done.'}
    result = [o for o in ORDERS if not status or o['status'] == status]
    result.sort(key=lambda o: (o['created_at'], o['id']))
    return 200, {'orders': result}


def _advance_order(order_id_text, body):
    try:
        order_id = int(order_id_text)
    except ValueError:
        return 400, {'error': 'Order id must be a number.'}
    data, err = _parse_body(body)
    if err:
        return 400, {'error': err}
    order = None
    for o in ORDERS:
        if o['id'] == order_id:
            order = o
            break
    if order is None:
        return 404, {'error': 'Order not found.'}
    index = STATUSES.index(order['status'])
    if index >= len(STATUSES) - 1:
        return 409, {'error': 'Order is already done.'}
    next_status = STATUSES[index + 1]
    requested = data.get('status')
    if requested is not None and requested != next_status:
        return 409, {'error': 'Invalid transition: an order can only move from %s to %s.' % (order['status'], next_status)}
    order['status'] = next_status
    return 200, {'order': order}


def _sales_today():
    today = datetime.date.today().isoformat()
    count = 0
    total = 0
    quantities = {}
    for o in ORDERS:
        if o['created_at'][:10] == today:
            count += 1
            total += o['total_cents']
            for it in o['items']:
                quantities[it['id']] = quantities.get(it['id'], 0) + it['quantity']
    ranked = sorted(quantities.items(), key=lambda kv: (-kv[1], MENU_INDEX.get(kv[0], 10 ** 6)))
    top_items = []
    for item_id, qty in ranked[:3]:
        top_items.append({
            'id': item_id,
            'name': MENU_BY_ID[item_id]['name'],
            'quantity': qty,
        })
    return 200, {
        'date': today,
        'order_count': count,
        'total_cents': total,
        'total': total / 100.0,
        'topItems': top_items,
    }


def handle(method, path, body):
    method = (method or '').upper()
    parts = [p for p in (path or '').split('/') if p]

    if parts == ['menu']:
        if method != 'GET':
            return 405, {'error': 'Method not allowed.'}
        return 200, {'menu': _menu_view()}

    if len(parts) == 3 and parts[0] == 'menu' and parts[2] == 'sold-out':
        if method not in ('PATCH', 'PUT', 'POST'):
            return 405, {'error': 'Method not allowed.'}
        return _set_sold_out(parts[1], body)

    if parts == ['orders']:
        if method == 'GET':
            return _list_orders(body)
        if method == 'POST':
            return _create_order(body)
        return 405, {'error': 'Method not allowed.'}

    if len(parts) == 3 and parts[0] == 'orders' and parts[2] == 'status':
        if method not in ('PATCH', 'PUT', 'POST'):
            return 405, {'error': 'Method not allowed.'}
        return _advance_order(parts[1], body)

    if parts == ['sales', 'today']:
        if method != 'GET':
            return 405, {'error': 'Method not allowed.'}
        return _sales_today()

    return 404, {'error': 'Not found.'}

