* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
  background: #faf6ef;
  color: #2d2a26;
}
header {
  background: #7a4a21;
  color: #fff;
  padding: 12px 16px 0;
}
header h1 { margin: 0 0 10px; font-size: 1.4rem; }
.tabs { display: flex; gap: 6px; flex-wrap: wrap; }
.tab {
  border: 0;
  background: #9a6335;
  color: #fff;
  padding: 10px 20px;
  font-size: 1rem;
  border-radius: 8px 8px 0 0;
  cursor: pointer;
}
.tab.active { background: #faf6ef; color: #7a4a21; font-weight: 700; }
main { max-width: 1000px; margin: 0 auto; padding: 16px; }
.panel.hidden, .hidden { display: none; }
h2 { margin-top: 0; }
.section-title { margin: 24px 0 10px; font-size: 1.15rem; }
.menu {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
  gap: 12px;
}
.card {
  background: #fff;
  border: 2px solid #e6dccb;
  border-radius: 10px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.card.selected { border-color: #7a4a21; background: #fff8ec; }
.card.sold-out {
  background: #e4e4e4;
  border-color: #c4c4c4;
  color: #8a8a8a;
}
.card.sold-out .card-price { color: #8a8a8a; }
.card.sold-out .card-name { text-decoration: line-through; }
.card-flag { font-weight: 700; color: #6e6e6e; }
.card-name { font-weight: 700; font-size: 1.05rem; }
.card-price { color: #6b6256; }
.qty { display: flex; align-items: center; gap: 12px; margin-top: 4px; }
.qty-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid #7a4a21;
  background: #fff;
  color: #7a4a21;
  font-size: 1.4rem;
  cursor: pointer;
}
.qty-btn:active { background: #f1e3cf; }
.qty-btn:disabled {
  border-color: #bdbdbd;
  background: #d6d6d6;
  color: #9a9a9a;
  cursor: not-allowed;
}
.qty-count { min-width: 28px; text-align: center; font-size: 1.2rem; font-weight: 700; }
.order-bar {
  margin-top: 16px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  background: #fff;
  border: 1px solid #e6dccb;
  border-radius: 10px;
  padding: 12px;
}
.order-bar input[type=text], .toolbar select {
  padding: 10px;
  font-size: 1rem;
  border: 1px solid #c9bda9;
  border-radius: 6px;
}
.order-bar input[type=text] { width: 110px; }
.order-type {
  display: flex;
  align-items: center;
  gap: 8px;
  border: 1px solid #c9bda9;
  border-radius: 8px;
  margin: 0;
  padding: 4px 10px 6px;
}
.order-type legend { font-size: 0.8rem; color: #6b6256; padding: 0 4px; }
.type-option {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  font-size: 1rem;
  cursor: pointer;
}
.type-option input { width: 18px; height: 18px; }
.total { margin-left: auto; font-size: 1.2rem; }
button.primary {
  background: #7a4a21;
  color: #fff;
  border: 0;
  border-radius: 8px;
  padding: 12px 20px;
  font-size: 1rem;
  cursor: pointer;
}
button.primary:disabled { opacity: 0.6; cursor: default; }
.toolbar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-bottom: 12px; }
.toolbar button {
  padding: 10px 16px;
  font-size: 1rem;
  border: 1px solid #7a4a21;
  background: #fff;
  color: #7a4a21;
  border-radius: 6px;
  cursor: pointer;
}
.message { min-height: 1.4em; margin: 10px 0 0; }
.message.ok { color: #1e7a3a; font-weight: 600; }
.message.error { color: #b3261e; font-weight: 600; }
.orders {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 12px;
}
.empty { color: #6b6256; }
.order {
  background: #fff;
  border: 1px solid #e6dccb;
  border-left: 8px solid #999;
  border-radius: 10px;
  padding: 12px;
}
.order.status-todo { border-left-color: #e8590c; }
.order.status-cooking { border-left-color: #f2b705; }
.order.status-done { border-left-color: #2f9e44; }
.order-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.order-title { font-weight: 700; }
.order-meta { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; margin: 6px 0 4px; }
.order-time { color: #6b6256; font-size: 0.9rem; }
.order-items { margin: 8px 0; padding-left: 20px; }
.order-foot { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.order-total { font-weight: 700; }
.badge {
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 0.85rem;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
}
.badge-todo { background: #e8590c; }
.badge-cooking { background: #f2b705; color: #3a2f00; }
.badge-done { background: #2f9e44; }
.type-badge {
  padding: 3px 10px;
  border-radius: 6px;
  font-size: 0.85rem;
  font-weight: 700;
  white-space: nowrap;
}
.type-dine_in { background: #dbeafe; color: #1e3a8a; border: 1px solid #93c5fd; }
.type-take_out { background: #fce7f3; color: #831843; border: 1px solid #f9a8d4; }
.availability {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 10px;
}
.avail-row {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #fff;
  border: 1px solid #e6dccb;
  border-radius: 10px;
  padding: 10px 12px;
}
.avail-row.is-sold-out { background: #e4e4e4; border-color: #c4c4c4; color: #7a7a7a; }
.avail-name { font-weight: 700; flex: 1; }
.avail-state { font-size: 0.85rem; color: #6b6256; }
.toggle {
  padding: 8px 12px;
  font-size: 0.9rem;
  border: 1px solid #7a4a21;
  background: #fff;
  color: #7a4a21;
  border-radius: 6px;
  cursor: pointer;
  white-space: nowrap;
}
.toggle.toggle-on { background: #7a4a21; color: #fff; }
.stats { display: flex; flex-wrap: wrap; gap: 12px; }
.stat {
  flex: 1 1 200px;
  background: #fff;
  border: 1px solid #e6dccb;
  border-radius: 10px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.stat-label { color: #6b6256; }
.stat-value { font-size: 2.2rem; font-weight: 700; color: #7a4a21; }
.top-items {
  margin: 0;
  padding-left: 28px;
  background: #fff;
  border: 1px solid #e6dccb;
  border-radius: 10px;
  padding-top: 8px;
  padding-bottom: 8px;
}
.top-items:empty { display: none; }
.top-item { padding: 8px 6px; font-size: 1.05rem; }
.top-item::marker { font-weight: 700; color: #7a4a21; }
.top-name { font-weight: 700; margin-right: 10px; }
.top-qty { color: #6b6256; }
@media (max-width: 520px) {
  main { padding: 12px; }
  .total { margin-left: 0; width: 100%; }
  .order-bar button.primary { width: 100%; }
  .order-type { width: 100%; justify-content: space-around; }
  .tab { flex: 1; padding: 12px 8px; }
  .avail-row { flex-wrap: wrap; }
}
